<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue';
import Modal from './Modal.vue';
import { api, all, type KnowledgeBase, type MCPServer, type ModelOption, type Skill } from '../lib/api';
import { createWriter, learningStates, type TemplateSummary, type TemplatePreview, type Adoption, type ImportBatch } from '../lib/learning';
const write=createWriter();
const props=defineProps<{ libraries: KnowledgeBase[]; models: ModelOption[]; skills: Skill[]; servers: MCPServer[]; adoptionId?: string; headless?:boolean }>();
const emit=defineEmits<{custom:[];adopted:[id:string];changed:[]}>();
const menu=ref(false),open=ref(false),loading=ref(false),busy=ref(false),error=ref(''),templates=ref<TemplateSummary[]>([]),selected=ref<TemplatePreview|null>(null),name=ref('');
const model=ref(''),mcp=ref<string[]>([]),skills=ref<string[]>([]),target=ref<'skip'|'new'|'existing'>('skip'),kbName=ref(''),kbId=ref('');
const adopted=ref<Adoption|null>(null),batch=ref<ImportBatch|null>(null),answers=ref(false),reimportConfirmed=ref(false);
let timer:ReturnType<typeof setTimeout>|undefined;
let revision=0;
const menuStyle=ref<Record<string,string>>({});
const availableModels=computed(()=>props.models.filter(m=>m.enabled));
const missingModel=computed(()=>!availableModels.value.some(m=>m.id===model.value));
const failed=computed(()=>batch.value?.items.filter(i=>i.can_retry).map(i=>i.id)??[]);
const terminal=new Set(['succeeded','completed','failed','partial_failed','partial_failure','stopped']);
function message(e:unknown){return e instanceof Error?e.message:'操作失败，请重试。';}
async function toggle(anchor?:HTMLElement){if(anchor){const r=anchor.getBoundingClientRect();menuStyle.value={position:'fixed',top:Math.min(r.bottom+4,innerHeight-160)+'px',left:Math.max(8,Math.min(r.left,innerWidth-288))+'px',width:Math.min(r.width||280,innerWidth-16)+'px',right:'auto',zIndex:'100'};}menu.value=!menu.value;if(!menu.value)return;loading.value=true;error.value='';try{templates.value=await all<TemplateSummary>('/agent-templates');}catch(e){error.value=message(e);}finally{loading.value=false;}}
async function preview(t:TemplateSummary){reimportConfirmed.value=false;open.value=true;menu.value=false;loading.value=true;error.value='';selected.value=null;adopted.value=null;batch.value=null;answers.value=false;clearTimeout(timer);try{const id=t.version_id??t.published_version_id;if(!id)throw new Error('该模板暂无可采用版本。');selected.value=await api<TemplatePreview>(`/agent-templates/${t.id}/versions/${id}`);name.value=t.name;model.value=selected.value.config_choices.model_id;mcp.value=[...selected.value.config_choices.mcp_server_ids];skills.value=[...selected.value.config_choices.skill_ids];target.value='skip';kbId.value=props.libraries[0]?.id??'';kbName.value=t.name+'资料';}catch(e){error.value=message(e);}finally{loading.value=false;}}
async function showAnswers(){if(!selected.value)return;busy.value=true;error.value='';try{selected.value=await api<TemplatePreview>(`/agent-templates/${selected.value.id}/versions/${selected.value.version_id}?include_answers=true`);answers.value=true;}catch(e){error.value=message(e);}finally{busy.value=false;}}
function importTarget(){if(target.value==='skip')return null;if(target.value==='new'){if(!kbName.value.trim())throw new Error('请填写新知识库名称。');return{new_kb_name:kbName.value.trim()};}if(!kbId.value)throw new Error('请选择个人知识库。');return{target_kb_id:kbId.value};}
async function poll(id:string){const current=++revision;try{const next=await api<ImportBatch>(`/template-imports/${id}`);if(current!==revision||!open.value)return;batch.value=next;if(!terminal.has(next.status))timer=setTimeout(()=>void poll(id),1800);else emit('changed');}catch(e){if(current===revision)error.value=message(e);}}
async function adopt(){if(!selected.value)return;busy.value=true;error.value='';try{const import_target=importTarget();adopted.value=await write<Adoption>('/template-adoptions','POST',{version_id:selected.value.version_id,name:name.value,config_overrides:{model_id:model.value,mcp_server_ids:mcp.value,skill_ids:skills.value},import_target});emit('adopted',adopted.value.agent_id);if(target.value==='skip')target.value='new';if(adopted.value.import_batch_id)await poll(adopted.value.import_batch_id);}catch(e){error.value=message(e);}finally{busy.value=false;}}
async function loadAdoption(){if(!props.adoptionId)return;reimportConfirmed.value=false;adopted.value=null;batch.value=null;clearTimeout(timer);++revision;open.value=true;menu.value=false;selected.value=null;loading.value=true;error.value='';try{adopted.value=await api<Adoption>(`/template-adoptions/${props.adoptionId}`);if(adopted.value.import_batch_id)await poll(adopted.value.import_batch_id);target.value='new';kbName.value='模板学习资料';kbId.value=props.libraries[0]?.id??'';}catch(e){error.value=message(e);}finally{loading.value=false;}}
async function startImport(){if(!adopted.value)return;busy.value=true;error.value='';try{const body=importTarget();if(!body)throw new Error('请选择导入目标。');const result=await write<any>(`/template-adoptions/${adopted.value.id}/imports`,'POST',{...body,confirm_reimport:reimportConfirmed.value});await poll(result.id??result.import_batch_id);}catch(e){error.value=message(e);}finally{busy.value=false;}}
async function retry(){if(!batch.value)return;busy.value=true;error.value='';try{const result=await write<any>(`/template-imports/${batch.value.id}/retry`,'POST',{item_ids:failed.value});await poll(result.id??batch.value.id);}catch(e){error.value=message(e);}finally{busy.value=false;}}
function close(){open.value=false;clearTimeout(timer);++revision;error.value='';}
watch(open,v=>{if(!v){clearTimeout(timer);++revision;}});
function dismiss(event:PointerEvent){if(!(event.target as HTMLElement).closest('.learning-create,.learning-create-menu,.resource-create'))menu.value=false;}
function escape(event:KeyboardEvent){if(event.key==='Escape')menu.value=false;}
onMounted(()=>{document.addEventListener('pointerdown',dismiss);document.addEventListener('keydown',escape);});
defineExpose({toggle,loadAdoption});
onBeforeUnmount(()=>{clearTimeout(timer);++revision;document.removeEventListener('pointerdown',dismiss);document.removeEventListener('keydown',escape);});
</script>
<template>
 <div class="learning-create"><button v-if="!headless" class="resource-create" aria-label="创建智能体" :aria-expanded="menu" @click="toggle()">＋ 创建智能体</button><Teleport to="body" :disabled="!headless"><div v-if="menu" class="learning-create-menu" :style="headless?menuStyle:undefined"><button @click="menu=false;emit('custom')">用户自定义</button><p v-if="loading" class="muted">正在载入模板…</p><p v-if="error" role="alert" class="learning-error">{{error}} <button @click="menu=false;toggle()">重试</button></p><button v-for="t in templates" :key="t.id" @click="preview(t)">{{t.name}}</button><p v-if="!loading&&!templates.length&&!error" class="muted">暂无上架模板，可以自定义创建。</p><button @click="menu=false">收起菜单</button></div></Teleport></div>
 <button v-if="adoptionId&&!headless" class="text-button" @click="loadAdoption">模板资料导入状态</button>
 <Modal :open="open" :title="adopted?'模板资料导入':selected?.name??'模板预览'" wide @close="close">
 <p v-if="error" class="learning-error" role="alert">{{error}}</p><p v-if="loading" role="status">正在载入…</p>
 <template v-if="selected&&!adopted"><p>{{selected.description}}</p><p class="learning-tag">采用指定版本创建独立副本，后续模板更新不会覆盖你的内容。</p><div class="learning-two"><section><h3>智能体配置</h3><p class="learning-preview">{{selected.config_choices.system_prompt}}</p></section><section><h3>{{selected.plan.title}}</h3><p>{{selected.plan.goal}}</p><p v-if="selected.plan.deadline">截止日期：{{selected.plan.deadline}}</p><div v-for="s in selected.plan.stages" :key="s.id"><b>{{s.title}}</b><p>{{s.goal}}</p><p>知识点：{{s.knowledge_points.join('、')}}</p><ul><li v-for="t in s.tasks" :key="t.id">{{t.title}} · {{t.estimated_minutes}} 分钟<p v-for="(tip,index) in t.exercise_suggestions" :key="index">{{tip}}</p><p v-if="t.resource_source_ids.length" class="muted">参考资料：{{t.resource_source_ids.map(id=>selected!.asset_manifest.find(a=>a.id===id)?.filename??'模板资料').join('、')}}</p></li></ul></div></section></div>
 <section><h3>练习（{{selected.exercises.length}}）</h3><div v-for="(q,i) in selected.exercises" :key="i" class="learning-card"><p class="learning-preview">{{i+1}}. {{q.question_text}}</p><div v-if="answers" class="learning-answer"><p>{{q.answer_text??'未提供答案，可采用后请求推导。'}}</p><p>{{q.explanation}}</p></div></div><button v-if="!answers" :disabled="busy" @click="showAnswers">查看模板已有答案与解析</button></section>
 <section><h3>专属资料</h3><ul><li v-for="(a,i) in selected.asset_manifest" :key="a.id??i">{{a.filename??a.original_name}} <span class="muted">（采用后可导入个人库）</span></li></ul></section>
 <form class="learning-form" @submit.prevent="adopt"><label>个人智能体名称<input v-model="name" required maxlength="50" /></label><label>生成模型<select v-model="model" required aria-label="生成模型"><option v-if="missingModel" :value="model">模板所选模型已不可用，请选择替代</option><option v-for="m in availableModels" :key="m.id" :value="m.id">{{m.display_name}}</option></select></label><fieldset><legend>MCP扩展</legend><label v-for="s in servers" :key="s.id" class="check-row"><input v-model="mcp" type="checkbox" :value="s.id" />{{s.name}}</label><label v-for="id in mcp.filter(id=>!servers.some(s=>s.id===id))" :key="id" class="check-row"><input v-model="mcp" type="checkbox" :value="id" />不可用服务 {{id}}（请取消）</label></fieldset><fieldset><legend>技能开启范围</legend><label v-for="s in props.skills" :key="s.id" class="check-row"><input v-model="skills" type="checkbox" :value="s.id" />{{s.name}}</label><label v-for="id in skills.filter(id=>!props.skills.some(s=>s.id===id))" :key="id" class="check-row"><input v-model="skills" type="checkbox" :value="id" />不可用技能 {{id}}（请取消）</label></fieldset>
 <label>模板资料<select v-model="target"><option value="skip">暂不导入，之后可补导入</option><option value="new">导入新知识库</option><option value="existing">导入已有个人知识库</option></select></label><label v-if="target==='new'">新知识库名称<input v-model="kbName" required maxlength="50" /></label><label v-if="target==='existing'">目标知识库<select v-model="kbId" required><option v-for="k in libraries" :key="k.id" :value="k.id">{{k.name}}</option></select></label><p class="muted">未导入的资料引用仅保留名称位置。导入成功后使用个人文件，全部完成后自动关联知识库。</p><button class="primary" :disabled="busy||missingModel">{{busy?'正在创建…':'采用模板并创建个人副本'}}</button></form></template>
 <template v-if="adopted"><p class="learning-success" role="status">个人智能体已创建；模板内容与个人副本独立。</p><section v-if="batch"><h3>资料导入 · {{learningStates[batch.status]??batch.status}}</h3><ol class="learning-import-items"><li v-for="(item,i) in batch.items" :key="item.id">{{item.filename??'资料 '+(i+1)}} · {{learningStates[item.status]??item.status}}<span v-if="item.error_code"> · {{item.error_code}}</span></li></ol><div class="learning-actions"><button v-if="failed.length" :disabled="busy" @click="retry">重试 {{failed.length}} 个失败文件</button><button :disabled="busy" @click="poll(batch!.id)">刷新状态</button></div></section><p v-else class="learning-message">尚未导入模板资料。引用会标记“模板资料未导入”。</p>
 <form class="learning-form" @submit.prevent="startImport"><h3>补导入资料</h3><label>导入目标<select v-model="target"><option value="new">新建个人知识库</option><option value="existing">已有个人知识库</option></select></label><label v-if="target==='new'">新知识库名称<input v-model="kbName" required maxlength="50" /></label><label v-if="target==='existing'">个人知识库<select v-model="kbId" required><option v-for="k in libraries" :key="k.id" :value="k.id">{{k.name}}</option></select></label><label class="check-row"><input v-model="reimportConfirmed" type="checkbox" />如曾删除个人复制文件，明确确认重新导入</label><button :disabled="busy||!!batch&&!terminal.has(batch.status)">开始补导入</button></form></template>
 </Modal>
</template>
